insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('chat-media','chat-media',false,104857600,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime','audio/webm','audio/ogg','audio/mpeg','audio/wav','audio/x-wav','audio/mp4','audio/x-m4a','application/pdf','text/plain','application/zip','application/x-zip-compressed','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
create policy nanba_media_read on storage.objects for select to authenticated using(bucket_id='chat-media' and exists(select 1 from public.conversation_members m where m.user_id=auth.uid() and m.conversation_id::text=(storage.foldername(name))[1]) and ((storage.foldername(name))[2]=auth.uid()::text or exists(select 1 from public.messages where media_path=name and deleted_for_everyone_at is null) or exists(select 1 from public.profiles where avatar_path=name)));
create policy nanba_media_upload on storage.objects for insert to authenticated with check(bucket_id='chat-media' and (storage.foldername(name))[2]=auth.uid()::text and exists(select 1 from public.conversation_members m where m.user_id=auth.uid() and m.conversation_id::text=(storage.foldername(name))[1]));
create policy nanba_media_remove on storage.objects for delete to authenticated using(bucket_id='chat-media' and (storage.foldername(name))[2]=auth.uid()::text and exists(select 1 from public.conversation_members m where m.user_id=auth.uid() and m.conversation_id::text=(storage.foldername(name))[1]) and not exists(select 1 from public.messages where media_path=name and deleted_for_everyone_at is null) and not exists(select 1 from public.profiles where avatar_path=name));
